ption {\r\n  width: 28px;\r\n  height: 28px;\r\n  border-radius: 50%;\r\n  border: 2px solid transparent;\r\n  cursor: pointer;\r\n  transition: transform 0.15s, border-color 0.15s;\r\n}\r\n.colorOption:hover { transform: scale(1.15); }\r\n.colorSelected { border-color: #000; transform: scale(1.15); }\r\n\r\n/* ── Button variants ────────────────────────────────────────────────────────── */\r\n\r\n.btnCancel {\r\n  padding: 7px 20px;\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 6px;\r\n  background: transparent;\r\n  color: var(--ds-color-text-secondary, #4A4A4A);\r\n  font-size: 14px;\r\n  cursor: pointer;\r\n}\r\n.btnCancel:hover { background: var(--ds-color-bg-subtle, #F6F6F6); }\r\n\r\n.btnSave {\r\n  padding: 7px 24px;\r\n  border: none;\r\n  border-radius: 6px;\r\n  background: var(--ds-color-primary, #2563eb);\r\n  color: #fff;\r\n  font-size: 14px;\r\n  font-weight: 500;\r\n  cursor: pointer;\r\n  min-width: 64px;\r\n}\r\n.btnSave:hover:not(:disabled) { background: var(--ds-color-primary-dark, #002450); }\r\n.btnSave:disabled { opacity: 0.6; cursor: not-allowed; }\r\n\r\n/* ── Responsive ─────────────────────────────────────────────────────────────── */\r\n\r\n@media (max-width: 900px) {\r\n  .widgetGrid { grid-template-columns: repeat(2, 1fr); }\r\n  .widgetCols2 { grid-column: span 2; }\r\n  .widgetCols3 { grid-column: span 2; }\r\n}\r\n\r\n@media (max-width: 640px) {\r\n  .quickLinkGrid { grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); }\r\n  .widgetGrid { grid-template-columns: 1fr; }\r\n  .widgetCols2, .widgetCols3 { grid-column: span 1; }\r\n}\r\n"],"sourceRoot":""}]);
