import React, { useEffect } from 'react';
import { navigateToUrl } from 'single-spa';
import { isStandalone } from '../../dev/isStandalone';

/** Embedded shell: login is on Home MFE — redirect via single-spa. */
export const AuthLoginRedirect: React.FC = () => {
  useEffect(() => {
    if (!isStandalone) {
      navigateToUrl('/login');
    }
  }, []);

  return null;
};
